package com.cpf.starter.tcp;import java.time.Duration;import java.util.SplittableRandom;public final class CpfTcpReconnectPolicy {private final Duration initial,max;private final double jitter;public CpfTcpReconnectPolicy(Duration i,Duration m,double j){if(i.isNegative()||i.isZero()||m.compareTo(i)<0||j<0||j>1)throw new IllegalArgumentException();initial=i;max=m;jitter=j;}public Duration delay(int attempt,long seed){long base=Math.min(max.toMillis(),Math.multiplyExact(initial.toMillis(),1L<<Math.min(20,Math.max(0,attempt))));double factor=1-jitter+(new SplittableRandom(seed).nextDouble()*jitter*2);return Duration.ofMillis(Math.max(1,(long)(base*factor)));}}
